const SOURCES = INVENTORY_SOURCES.filter((s) => ["budge-legends-1912", "hornung-cow", "lichtheim-ael"].includes(s.key));

export const BUDGE_COW_EVIDENCE =
  "E. A. Wallis Budge, Legends of the Gods (1912), 'The Legend of the Destruction of Mankind', public domain (published 1912; Budge died in 1934). Taken from the Project Gutenberg e-text (no. 9411) and compared word by word with archive.org OCRs of two printed copies of the book; where the two printed copies agree against the e-text, their reading is taken unless both OCRs misread the same printed word alike, and every such decision and every correction by hand is listed in scripts/texts/budge-heavenly-cow.py. No page image was compared by eye. Budge's hieroglyphic text, transliteration and footnotes are left out; the few Egyptian words he gives in brackets inside the English are kept, without their long-vowel marks. His rows of dots for gaps in the Egyptian text are kept as '. . . . .', and his square brackets mark words he supplies.";

function budgeLayer(part: CowPart): CorpusLayer {
  return {
    key: "eng-budge",
    layer: "translation",
    sourceKey: "budge-legends-1912",
    content: part.text,
    language: "English",
    licence: "public_domain",
    evidence: `${BUDGE_COW_EVIDENCE} (${part.pages})`,
  };
}

function cited(section: number): CorpusLayer[] {
  const layers = [
    citedLayer(
      "deu-hornung",
      "hornung-cow",
      "E. Hornung, Der ägyptische Mythos von der Himmelskuh: Eine Ätiologie des Unvollkommenen (OBO 46, 1982)",
      `The critical edition of the book from all its royal copies, with a German translation; Budge's section ${NUMERALS[section]} is not matched to Hornung's numbering here.`,
    ),
  ];
  if (section === 1) {
    layers.push(
      citedLayer(
        "eng-lichtheim",
        "lichtheim-ael",
        "M. Lichtheim, Ancient Egyptian Literature, vol. II: The New Kingdom (1976), 'The Destruction of Mankind'",
        "A modern English translation of the narrative.",
      ),
    );
  }
  return layers;
}

